def check_equation(p, a):
    """Checks if p^a = 12a + 1 for prime p and integer a >= 1."""
    if not isinstance(p, int) or p < 2:
        return False
    if not isinstance(a, int) or a < 1:
        return False

    # Check if p is prime (basic check, since we are testing primes, this is mostly for safety)
    def is_prime(n):
        if n <= 1: return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0: return False
        return True

    if not is_prime(p):
        return False

    left = p**a
    right = 12*a + 1
    return left == right, left, right

