def tau_n_12(n):
    if n == 1:
        return 1

    # Find prime factorization of n
    factors = {}
    d = 2
    temp_n = n
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

    # Calculate tau(n^12)
    tau = 1
    for p, a in factors.items():
        # Exponent of p in n^12 is 12*a
        # The factor in tau is (12*a + 1)
        tau *= (12 * a + 1)
    return tau

solutions_to_check = [1, 13, 25, 325]
results = {}

for n in solutions_to_check:
    calculated_tau = tau_n_12(n)
    satisfies = (n == calculated_tau)
    results[n] = (calculated_tau, satisfies)

print("--- Verification Results ---")
for n, (tau_val, satisfies) in results.items():
    print(f"For n = {n}: tau(n^12) = {tau_val}. Does n = tau(n^12)? {'Yes' if satisfies else 'No'}")

